import { atom, read, update } from 'claude-code'
import type { EngineInterface, ModelForkResult, Register, RenderElement } from 'claude-code'

import type { CacheView, Warmth } from '../types'

const OFF: Warmth = {
  isOn: false,
  isCompactOn: false,
  pings: 0,
  isPinging: false,
  isArmed: true,
  retryAt: 0,
}

const viewAtom = atom({ plugin: 'cache-band', key: 'view' } as const, null)
const compactingAtom = atom({ plugin: 'cache-band', key: 'isCompacting' } as const, false)
const warmthAtom = atom({ plugin: 'cache-band', key: 'warmth' } as const, OFF)

// This plan keeps the prompt cache for an hour after the last request.
const TTL_MS = 60 * 60_000
// Auto cache pings this long before the cache would go cold.
const LEAD_MS = 10 * 60_000
// A ping re-reads the conversation at a tenth of the input price, and a cold
// rewrite costs twice that price, so 20 pings in a row cost what the rewrite
// they prevent would (about 16 hours away). Past that, pings stop.
const MAX_PINGS = 20
const RETRY_MS = 5 * 60_000
// Auto compact compacts once the conversation passes this size. Every message
// re-reads the whole conversation, so its cost grows with it, and so does the
// share of what Claude misses (Chroma's context rot study; on MRCR v2's
// 8-needle test at 1M tokens, Opus 4.6 found 76%). Anthropic's API compaction
// fires at 150k by default, and Claude Code's own waits until about 83% of the
// window, some 830k of 1M. 400k sits between: twice the old 200k window for
// long tasks, at under half the per-message cost of 830k.
const AUTO_COMPACT_AT = 400_000
// After a compaction that failed, Auto compact waits this long to try again.
const COMPACT_RETRY_MS = 30 * 60_000
const PING =
  'Automatic keep-alive from the cache-band mod, sent to keep the prompt cache warm. It is not a message from the person. Use no tools. Reply with only: ok'
const CELLS = 12
// Eighth-cell steps. Block characters are drawn in the code font on desktop,
// so the meter comes out even.
const BLOCKS = ['', '▏', '▎', '▍', '▌', '▋', '▊', '▉']

const EMPTY: CacheView = { lastUsedAt: 0, ctxTokens: 0, ctxOverride: null, now: 0 }

type Temperature = { word: string; tone: string; leftMs: number }

const tokens = (n: number) =>
  n >= 1_000_000 ? `${+(n / 1_000_000).toFixed(1)}M` : `${Math.round(n / 1000)}k`

const span = (ms: number) => {
  const m = Math.max(0, Math.round(ms / 60_000))
  if (m < 60) return `${m}m`
  const h = Math.floor(m / 60)

  return m % 60 ? `${h}h ${m % 60}m` : `${h}h`
}

// Hot for the first 20 minutes, warm to 40, cooling to cold at 60. The colors
// are theme names (the app's orange, amber and blue), so they follow the theme.
const temperatureOf = (idleMs: number): Temperature => {
  const leftMs = Math.max(0, TTL_MS - idleMs)
  if (leftMs === 0) return { word: 'cold', tone: 'permission', leftMs }
  if (leftMs > 40 * 60_000) return { word: 'hot', tone: 'claude', leftMs }
  if (leftMs > 20 * 60_000) return { word: 'warm', tone: 'warning', leftMs }

  return { word: 'cooling', tone: 'permission', leftMs }
}

const meterOf = (share: number) => {
  const eighths = Math.round(Math.min(1, Math.max(0, share)) * CELLS * 8)
  const full = Math.floor(eighths / 8)
  const part = BLOCKS[eighths % 8] ?? ''

  return {
    filled: '█'.repeat(full) + part,
    empty: '░'.repeat(Math.max(0, CELLS - full - (part ? 1 : 0))),
  }
}

// The pictures are drawn as images, which can't read the app's theme, so their
// colors are literal: mid-tones that hold on the light and the dark background
// alike, close to the app's orange, amber and blue.
const PAINT: Record<string, { top: string; bottom: string; core: string }> = {
  hot: { top: '#F7B267', bottom: '#D97757', core: '#FFE3B8' },
  warm: { top: '#F5D06E', bottom: '#DFA13A', core: '#FFF1C7' },
  cooling: { top: '#AEBBFF', bottom: '#6C84EE', core: '#E1E6FF' },
  cold: { top: '#AEBBFF', bottom: '#6C84EE', core: '#E1E6FF' },
}
const TRACK = 'rgba(128,128,128,0.24)'

const FLAME =
  'M7 .8C7.6 2.6 9.1 3.9 10.2 5.4 11.1 6.6 11.6 7.8 11.6 9.1 11.6 11.6 9.5 13.4 7 13.4 4.5 13.4 2.4 11.6 2.4 9.1 2.4 7.4 3.3 6 4.4 5.1 4.5 6.3 5.1 7.2 5.9 7.6 5.6 5.2 6.1 2.6 7 .8Z'
const FLAME_CORE =
  'M7.1 7.4C8.2 8.5 9.1 9.4 9.1 10.7 9.1 11.9 8.2 12.7 7.1 12.7 6 12.7 5.1 11.9 5.1 10.8 5.1 9.7 5.9 8.7 7.1 7.4Z'

// Six arms, each with a pair of short branches pointing out.
const SNOWFLAKE = (() => {
  const at = (r: number, deg: number) => {
    const a = (deg * Math.PI) / 180

    return `${(7 + r * Math.cos(a)).toFixed(2)} ${(7.1 + r * Math.sin(a)).toFixed(2)}`
  }
  let d = ''
  for (let deg = -90; deg < 270; deg += 60) {
    d += `M7 7.1L${at(5.9, deg)}`
    d += `M${at(5, deg - 19)}L${at(3.6, deg)}L${at(5, deg + 19)}`
  }

  return d
})()

// The icon's share of the gauge, before the bar starts.
const GAUGE_ICON = 21

// The cache's icon and how much of its hour is left, as one strip; `tw` is
// the bar's length.
const gaugeSvg = (word: string, share: number, tw: number) => {
  const paint = PAINT[word] ?? PAINT.cold!
  const [x, h, th] = [GAUGE_ICON, 16, 6]
  const w = x + tw
  const ty = (h - th) / 2
  const fill = word === 'cold' ? 0 : Math.max(th, Math.round(Math.min(1, share) * tw))
  const icon =
    word === 'cold'
      ? `<path d="${SNOWFLAKE}" fill="none" stroke="${paint.bottom}" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round"/>`
      : `<path d="${FLAME}" fill="url(#cb-flame)"/><path d="${FLAME_CORE}" fill="${paint.core}" opacity=".9"/>`
  const glow =
    word === 'hot'
      ? `<rect x="${x}" y="${ty}" width="${fill}" height="${th}" rx="${th / 2}" fill="${paint.bottom}" opacity=".55" filter="url(#cb-glow)"/>`
      : ''
  const bar = fill
    ? `${glow}<rect x="${x}" y="${ty}" width="${fill}" height="${th}" rx="${th / 2}" fill="url(#cb-bar)"/>`
    : ''

  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">` +
    `<defs>` +
    `<linearGradient id="cb-flame" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${paint.top}"/><stop offset="1" stop-color="${paint.bottom}"/></linearGradient>` +
    `<linearGradient id="cb-bar" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="${paint.bottom}"/><stop offset="1" stop-color="${paint.top}"/></linearGradient>` +
    `<filter id="cb-glow" x="-10%" y="-120%" width="120%" height="340%"><feGaussianBlur stdDeviation="1.6"/></filter>` +
    `</defs>` +
    `<g transform="translate(0 1)">${icon}</g>` +
    `<rect x="${x}" y="${ty}" width="${tw}" height="${th}" rx="${th / 2}" fill="${TRACK}"/>` +
    bar +
    `</svg>`
  )
}

// Compact as an icon: two arrows closing in on the middle.
const COMPACT_PATH = 'M4 14h6v6M3 21l7-7M20 10h-6V4M21 3l-7 7'
const COMPACT_INK = '#A3A095'
const compactSvg = (isFaded: boolean) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="${COMPACT_INK}" ` +
  `stroke-opacity="${isFaded ? 0.4 : 1}" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">` +
  `<path d="${COMPACT_PATH}"/></svg>`

// A loop arrow going round: clockwise from the upper right to the top, where
// its head points on.
const LOOP = (() => {
  const at = (deg: number, r: number) => {
    const a = (deg * Math.PI) / 180

    return [12 + r * Math.cos(a), 12 + r * Math.sin(a)] as const
  }
  // As wide as Auto compact's ring, so the two icons match.
  const r = 9.4
  const fix = (n: number) => n.toFixed(2)
  const [sx, sy] = at(-35, r)
  const [ex, ey] = at(-95, r)
  const a = (-95 * Math.PI) / 180
  const [tx, ty] = [-Math.sin(a), Math.cos(a)]
  const [nx, ny] = [Math.cos(a), Math.sin(a)]
  const head =
    `M${fix(ex + 2.5 * nx)} ${fix(ey + 2.5 * ny)}L${fix(ex + 3.2 * tx)} ${fix(ey + 3.2 * ty)}` +
    `L${fix(ex - 2.5 * nx)} ${fix(ey - 2.5 * ny)}Z`

  return { arc: `M${fix(sx)} ${fix(sy)}A${r} ${r} 0 1 1 ${fix(ex)} ${fix(ey)}`, head }
})()

// A toggle drawn as an icon: orange in a soft glow when it's on, plain grey
// when it's off. `draw` paints the icon in the color it's handed.
const glowingSvg = (draw: (ink: string) => string, isOn: boolean) => {
  const shape = draw(isOn ? '#F28B54' : 'rgba(140,140,140,0.85)')

  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24">` +
    (isOn
      ? `<defs><radialGradient id="cb-halo"><stop offset="0" stop-color="#F5A15E" stop-opacity=".8"/>` +
        `<stop offset=".55" stop-color="#F5A15E" stop-opacity=".35"/>` +
        `<stop offset="1" stop-color="#F5A15E" stop-opacity="0"/></radialGradient>` +
        `<filter id="cb-blur" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="2"/></filter></defs>` +
        `<circle cx="12" cy="12" r="12" fill="url(#cb-halo)"/><g filter="url(#cb-blur)">${shape}</g>`
      : '') +
    shape +
    `</svg>`
  )
}

// Auto cache: the loop arrow.
const autoCacheSvg = (isOn: boolean) =>
  glowingSvg(
    ink =>
      `<path d="${LOOP.arc}" fill="none" stroke="${ink}" stroke-width="2.4" stroke-linecap="round"/>` +
      `<path d="${LOOP.head}" fill="${ink}" stroke="${ink}" stroke-width="1" stroke-linejoin="round"/>`,
    isOn,
  )

// Auto compact: Compact's arrows inside a ring.
const autoCompactSvg = (isOn: boolean) =>
  glowingSvg(
    ink =>
      `<circle cx="12" cy="12" r="9.8" fill="none" stroke="${ink}" stroke-width="2"/>` +
      `<path d="${COMPACT_PATH}" fill="none" stroke="${ink}" stroke-width="3.6" stroke-linecap="round" ` +
      `stroke-linejoin="round" transform="translate(12 12) scale(.52) translate(-12 -12)"/>`,
    isOn,
  )

// A picture takes no click, so each one a person presses has a blank button
// laid over it, centered on it: the button takes the click, and its hover
// frames the picture. Its label is two blank Braille cells (0.65em each in the
// symbol font Windows falls back to), enough to span an icon.
const ICON_BLANK = '⠀⠀'

// The layout is the fullest that fits the band's width in one row: every word;
// then without the word "Cache" and the toggles' names; then icons alone (the
// gauge, Auto cache, Auto compact and Compact), the words moving to hover
// cards. It is measured with the longest status this conversation can show,
// so it holds still as the status changes. Below TINY cells the bar shortens.
const TINY = 30

// Widths in the band's cells: its sans text runs about three quarters of a
// cell a character, and a cell is about 7.8 pixels.
const textCells = (text: string) => text.length * 0.75
const pxCells = (px: number) => px / 7.8
// A plain button's padding, both sides together, and an icon's blank button.
const PAD = pxCells(12)
const ICON_BUTTON = pxCells(30)

const slugOf = (path: string) => path.replace(/[^a-zA-Z0-9]/g, '-')

// Whether Auto cache will ping before the cache goes cold.
const willPing = (w: Warmth) => w.isOn && w.isArmed && w.pings < MAX_PINGS

// When the conversation last changed: its transcript's last write, which is
// the end of the last reply. 0 when the transcript can't be found.
async function lastWriteOf($: EngineInterface) {
  const home = (await $.env.get('USERPROFILE')) ?? (await $.env.get('HOME'))
  if (!home) return 0
  const projects = `${home.replace(/\\/g, '/')}/.claude/projects`
  const file = `${await $.session.id()}.jsonl`
  const guesses = [slugOf(await $.session.root()), slugOf(await $.session.cwd())]
  for (const dir of guesses) {
    const found = await $.fs.stat(`${projects}/${dir}/${file}`).catch(() => undefined)
    if (found) return found.mtimeMs
  }
  // The session moved since it started: look for its transcript by name.
  const dirs = await $.fs.list(projects).catch(() => [])
  for (const dir of dirs) {
    if (dir.kind !== 'dir' || guesses.includes(dir.name)) continue
    const found = await $.fs.stat(`${projects}/${dir.name}/${file}`).catch(() => undefined)
    if (found) return found.mtimeMs
  }

  return 0
}

async function refresh($: EngineInterface) {
  const [u, now] = await Promise.all([$.session.usage(), $.clock.now()])
  await update($, viewAtom, v => {
    const view = v ?? EMPTY

    return { ...view, ctxTokens: view.ctxOverride ?? u.context.tokens ?? 0, now }
  })
}

// A request of the main conversation read its cache, which now keeps for an
// hour from when the request was sent. Pings count from zero again.
async function noteRequest($: EngineInterface, sentAt: number) {
  await update($, viewAtom, v => ({ ...(v ?? EMPTY), lastUsedAt: Math.max(v?.lastUsedAt ?? 0, sentAt) }))
  await update($, warmthAtom, w => ({ ...w, pings: 0, isArmed: true, retryAt: 0 }))
}

// Set when a compaction lands during a turn, so that turn's end keeps the
// estimate instead of the stale size the summary request reported.
let compactedThisTurn = false

// Whether a turn of the main conversation is running; Auto compact waits.
let isTurnRunning = false

// Until the next reply reports the real size, estimate the conversation from
// what a compaction kept, at about four characters a token.
async function noteCompacted($: EngineInterface, kept: readonly { text: string }[]) {
  const chars = kept.reduce((sum, m) => sum + m.text.length, 0)
  const now = await $.clock.now()
  await update($, viewAtom, v => ({
    ...(v ?? EMPTY),
    lastUsedAt: now,
    ctxOverride: Math.round(chars / 4),
  }))
  // The last request was the long conversation; a ping would repeat it. Wait
  // for the compacted one to be sent.
  await update($, warmthAtom, w => ({ ...w, isArmed: false }))
  await update($, compactingAtom, () => false)
  await refresh($)
}

// Runs /compact as if typed. The desktop app runs Claude Code as an SDK
// session, where $.session.compact is refused and a compaction only runs as a
// /compact of its own; the command is queued until Claude is idle.
async function compactNow($: EngineInterface) {
  if (await read($, compactingAtom)) return
  await update($, compactingAtom, () => true)
  try {
    await $.command.run({ command: 'compact' })
    // The session.compact hook below normally saw it land. If it didn't, size
    // the conversation from what's left of it.
    if (await read($, compactingAtom)) await noteCompacted($, await $.session.messages())
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error)
    $.ui.toast(`Couldn't compact: ${reason}`.slice(0, 160))
    await update($, compactingAtom, () => false)
  }
}

// What a ping's reply says about the cache. Its usage tells whether the API
// served the conversation from the cache; a ping that paid for it in full
// found the cache already gone, and pinging again would pay in full each time.
async function settlePing($: EngineInterface, result: ModelForkResult, sentAt: number) {
  if (!result.isAnswered) {
    if (result.reason === 'nothing-to-fork') {
      await update($, warmthAtom, w => ({ ...w, isArmed: false }))
      return
    }
    if (result.reason === 'aborted') return
    if (result.reason === 'api-error') {
      await update($, warmthAtom, w => ({ ...w, retryAt: sentAt + RETRY_MS }))
      return
    }
  }
  // An answer, or a reply with no text: the request was made either way.
  const usage = result.usage
  const cached = usage.cache_read_input_tokens + usage.cache_creation_input_tokens
  if (cached === 0 || usage.input_tokens > cached) {
    await update($, warmthAtom, w => ({ ...w, isArmed: false }))
    $.ui.toast('Auto cache paused: the cache had already gone cold. It starts again after your next message.')
    return
  }
  await update($, viewAtom, v => ({ ...(v ?? EMPTY), lastUsedAt: sentAt }))
  await update($, warmthAtom, w => ({ ...w, pings: w.pings + 1 }))
}

// Taken before the first await, so a tick and a press can't both act.
let isActing = false

// Auto cache, shortly before the cache would go cold: $.model.fork sends the
// main conversation's last request again with a one-line question, the API
// serves it from the cache and keeps the cache another hour, the reply is
// dropped, and nothing joins the conversation.
async function beforeCold($: EngineInterface) {
  if (isActing) return
  isActing = true
  try {
    const [warmth, view, now] = await Promise.all([read($, warmthAtom), read($, viewAtom), $.clock.now()])
    if (!willPing(warmth) || !view || view.lastUsedAt === 0 || now < warmth.retryAt) return
    const leftMs = TTL_MS - (now - view.lastUsedAt)
    if (leftMs <= 0 || leftMs > LEAD_MS) return

    await update($, warmthAtom, w => ({ ...w, isPinging: true }))
    try {
      await settlePing($, await $.model.fork({ prompt: PING }), now)
    } catch {
      await update($, warmthAtom, w => ({ ...w, retryAt: now + RETRY_MS }))
    } finally {
      await update($, warmthAtom, w => ({ ...w, isPinging: false }))
    }
  } finally {
    isActing = false
  }
}

// When Auto compact last tried; a compaction that failed is not retried soon.
let lastAutoCompactAt = -Infinity

// Auto compact: once the conversation has passed AUTO_COMPACT_AT, compact it
// between turns, right after Claude's reply, while the cache is warm and
// reading the conversation for its summary is cheap.
async function maybeAutoCompact($: EngineInterface) {
  const [warmth, view, isCompacting, now] = await Promise.all([
    read($, warmthAtom),
    read($, viewAtom),
    read($, compactingAtom),
    $.clock.now(),
  ])
  if (!warmth.isCompactOn || !view || view.ctxTokens < AUTO_COMPACT_AT) return
  if (isTurnRunning || isCompacting || now - lastAutoCompactAt < COMPACT_RETRY_MS) return
  lastAutoCompactAt = now
  await compactNow($)
}

async function tick($: EngineInterface) {
  await refresh($)
  await beforeCold($)
  await maybeAutoCompact($)
}

// Turning Auto cache on inside the last 10 minutes pings right away, and
// Auto compact on past its size compacts right away.
async function toggleAutoCache($: EngineInterface) {
  await update($, warmthAtom, w => ({ ...w, isOn: !w.isOn }))
  await beforeCold($)
}

async function toggleAutoCompact($: EngineInterface) {
  await update($, warmthAtom, w => ({ ...w, isCompactOn: !w.isCompactOn }))
  await maybeAutoCompact($)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const view = await read($, viewAtom)
    if (!view || !view.lastUsedAt) {
      const at = await lastWriteOf($)
      await update($, viewAtom, v => ({ ...EMPTY, ctxOverride: v?.ctxOverride ?? null, lastUsedAt: at }))
    }
    // A ping the last load had out ended with it.
    await update($, warmthAtom, w => ({ ...w, isPinging: false }))
    await refresh($)
    $.clock.every(30_000, () => void tick($))

    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    isTurnRunning = true

    return next(e)
  })

  // Each request the main conversation sends reads its cache: the meter's
  // clock starts over from when it was sent, once the API has answered it.
  on('turn.step', async function* ($, e, next) {
    if (e.agentId) return yield* next(e)
    const sentAt = await $.clock.now()
    const result = yield* next(e)
    if (result.usage) await noteRequest($, sentAt)

    return result
  })

  // Every compaction that lands, wherever it came from: this band's button,
  // Auto compact, a typed /compact, or Claude Code's own.
  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    if (!e.agentId && e.trigger !== 'precompute' && result.skip === undefined) {
      compactedThisTurn = true
      await noteCompacted($, result.messages)
    }

    return result
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (!e.agentId) {
      isTurnRunning = false
      const keepsEstimate = compactedThisTurn
      compactedThisTurn = false
      await update($, viewAtom, v => ({
        ...(v ?? EMPTY),
        ctxOverride: keepsEstimate ? (v?.ctxOverride ?? null) : null,
      }))
      await update($, compactingAtom, () => false)
      await refresh($)
      // The reply is in: Auto compact looks once the turn has let go.
      $.clock.after(1_000, () => void maybeAutoCompact($))
    }

    return done
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const view = (await read($, viewAtom)) ?? EMPTY
    // A new session, before its first reply: nothing is cached yet. The band
    // shows from the start anyway, so the toggles can be set before then.
    const isFresh = view.lastUsedAt === 0 || view.ctxTokens === 0

    const [isCompacting, warmth] = await Promise.all([read($, compactingAtom), read($, warmthAtom)])
    const below = await next(e)
    const table = $.ui.resolve(e)
    const { Box, Text, Button } = table
    // The terminal has no Svg (its table hands one out that draws nothing), so
    // it keeps the meter of block characters and words for the toggles.
    const Svg = e.surface !== 'terminal' && 'Svg' in table ? table.Svg : undefined

    const isWorking = e.props.isWorking
    const t = temperatureOf(isWorking ? 0 : isFresh ? TTL_MS : Math.max(0, view.now - view.lastUsedAt))
    const isEmpty = isFresh && !isWorking
    const isCold = t.leftMs === 0
    const { filled, empty } = meterOf(t.leftMs / TTL_MS)
    const size = tokens(view.ctxTokens)
    const untilAct = t.leftMs - LEAD_MS
    const soon = untilAct < 60_000 ? '<1m' : span(untilAct)
    const status = isWorking
      ? 'in use'
      : isEmpty
        ? 'no cache yet'
        : isCold
          ? `next message rewrites ${size}`
          : warmth.isPinging
            ? 'pinging…'
            : willPing(warmth)
              ? `ping in ${soon}`
              : `cold in ${span(t.leftMs)}`

    // The cells each layout takes in one row, with the longest status.
    const columns = e.props.bodyColumns
    const cacheCells =
      (Svg ? pxCells(GAUGE_ICON + 105) : CELLS) + 1 + textCells('cooling') + 1 + textCells(`· next message rewrites ${size}`)
    const named = (name: string) => (Svg ? ICON_BUTTON + 1 + textCells(name) : textCells(`☐ ${name}`)) + PAD
    const togglesFull = named('Auto cache') + 2 + named('Auto compact')
    const togglesShort = Svg ? ICON_BUTTON + 1 + ICON_BUTTON : togglesFull
    const compactCells = textCells('Compact') + PAD
    const fullCells = Math.ceil(textCells('Cache') + 1 + cacheCells + 3 + togglesFull + 2 + compactCells)
    const mediumCells = Math.ceil(cacheCells + 3 + togglesShort + 2 + compactCells)
    const layout = columns >= fullCells ? 'full' : columns >= mediumCells || !Svg ? 'medium' : 'icons'
    const isFull = layout === 'full'
    const isIcons = layout === 'icons'
    const bar = isIcons && columns < TINY ? 64 : 105
    // A terminal narrower still keeps the cold status short.
    const shownStatus = !Svg && columns < mediumCells && isCold && !isEmpty ? 'full rewrite next' : status

    // A card that opens while the pointer is over the keyed Box around it; the
    // first of several lines is its heading.
    const card = (...lines: string[]) => (
      <Box
        position="absolute"
        top={-4}
        left={0}
        display="none"
        hover={{ display: 'flex' }}
        flexDirection="column"
        rowGap={1}
        borderStyle="round"
        borderColor="subtle"
        backgroundColor="background"
        paddingX={1}
      >
        {lines.map((line, i) => (
          <Text bold={isIcons && i === 0 && lines.length > 2}>{line}</Text>
        ))}
      </Box>
    )

    // A picture a person presses: a blank button laid over it and centered on
    // it takes the click, and its hover frames the picture.
    const pressable = (key: string, picture: RenderElement, onPress: () => void, tip?: string) => (
      <Box key={`${key}-box`} position="relative" flexDirection="row" alignItems="center" flexShrink={0}>
        {picture}
        <Box
          position="absolute"
          top={0}
          left={0}
          right={0}
          height="100%"
          flexDirection="row"
          alignItems="center"
          justifyContent="center"
        >
          <Button key={key} label={ICON_BLANK} plain onPress={onPress} />
        </Box>
        {tip !== undefined && card(tip)}
      </Box>
    )

    // A toggle: its glowing icon, named beside it when the band has room and
    // in a hover card when it hasn't. The terminal gets a box and its name.
    const toggle = (key: string, name: string, isOn: boolean, svg: (isOn: boolean) => string, does: string, onPress: () => void) => {
      if (!Svg) {
        return <Button key={key} label={`${isOn ? '☑' : '☐'} ${name}`} plain dimColor={!isOn} onPress={onPress} />
      }
      const state = `${name} ${isOn ? 'on' : 'off'}`
      const icon = pressable(
        key,
        <Svg source={svg(isOn)} alt={state} width={18} height={18} />,
        onPress,
        isFull ? undefined : `${state}: ${does}`,
      )
      if (!isFull) return icon

      return (
        <Box key={`${key}-named`} flexDirection="row" alignItems="center" columnGap={1} flexShrink={0}>
          {icon}
          <Button key={`${key}-name`} label={name} plain dimColor={!isOn} onPress={onPress} />
        </Box>
      )
    }

    // Each piece keeps its size; nothing wraps mid-phrase.
    const gauge = Svg ? (
      <Box flexShrink={0}>
        <Svg
          source={gaugeSvg(t.word, t.leftMs / TTL_MS, bar)}
          alt={isEmpty ? 'No cache yet' : isCold ? 'Cache cold' : `Cache ${t.word}, ${span(t.leftMs)} left`}
          width={GAUGE_ICON + bar}
          height={16}
        />
      </Box>
    ) : (
      <Box flexDirection="row" flexShrink={0}>
        <Text color={t.tone}>{filled}</Text>
        <Text color="rate_limit_empty">{empty}</Text>
      </Box>
    )

    const about = [
      (isEmpty
        ? `Claude starts caching this conversation with your first message, and keeps it for an hour after ` +
          `it last used it.`
        : `Claude keeps this conversation cached for an hour after it last used it.`) +
        ` While it's warm, each message re-reads it from the cache, which costs far less. Once it's cold, ` +
        `the next message writes it all into the cache again` +
        (isEmpty ? '.' : ` (${size} tokens now).`) +
        ` Compact shrinks the conversation, so both cost less.`,
      `Auto cache pings a background copy of the conversation 10 minutes before the cache would go cold, ` +
        `which keeps it hot without adding anything to the chat. A ping costs about a twentieth of a ` +
        `rewrite, so it stops after ${MAX_PINGS} in a row (about 16 hours away) and starts again when you ` +
        `send a message.` +
        (warmth.pings > 0 ? ` Pinged ${warmth.pings}× since your last message.` : ''),
      `Auto compact compacts the conversation once it passes ${tokens(AUTO_COMPACT_AT)} tokens, right ` +
        `after Claude's reply. Past that size every message costs more and Claude misses more of what's ` +
        `in it; Claude Code's own auto-compact would wait until about 830k.`,
    ]
    const word = t.word.charAt(0).toUpperCase() + t.word.slice(1)

    const cache = (
      <Box key="cache" flexDirection="row" alignItems="center" columnGap={1} flexShrink={0}>
        {isFull && (
          <Text dimColor wrap="truncate">
            Cache
          </Text>
        )}
        {gauge}
        {!isIcons && !isEmpty && (
          <Text color={t.tone} bold wrap="truncate">
            {t.word}
          </Text>
        )}
        {!isIcons && (
          <Text dimColor wrap="truncate">
            · {shownStatus}
          </Text>
        )}
        {isIcons
          ? card(isEmpty ? 'No cache yet · it starts with your first message' : `${word} · ${status}`, ...about)
          : card(...about)}
      </Box>
    )

    const autoCache = toggle(
      'auto',
      'Auto cache',
      warmth.isOn,
      autoCacheSvg,
      "keeps the cache warm while you're away",
      () => void toggleAutoCache($),
    )
    const autoCompact = toggle(
      'auto-compact',
      'Auto compact',
      warmth.isCompactOn,
      autoCompactSvg,
      `compacts the conversation past ${tokens(AUTO_COMPACT_AT)} tokens`,
      () => void toggleAutoCompact($),
    )

    // Nothing to compact before the first reply, nor while Claude works.
    const compact = isWorking || isEmpty ? null : isIcons && Svg ? (
      pressable(
        'compact',
        <Svg source={compactSvg(isCompacting)} alt={isCompacting ? 'Compacting' : 'Compact'} width={14} height={14} />,
        () => void compactNow($),
        isCompacting ? 'Compacting…' : 'Compact now',
      )
    ) : isCompacting ? (
      <Text dimColor wrap="truncate">
        compacting…
      </Text>
    ) : (
      <Button key="compact" label="Compact" plain onPress={() => void compactNow($)} />
    )

    return (
      <Box flexDirection="column">
        <Box
          flexDirection="row"
          flexWrap="wrap"
          alignItems="center"
          justifyContent="space-between"
          width="100%"
          columnGap={isIcons ? 2 : 3}
        >
          {cache}
          <Box
            key="controls"
            flexDirection="row"
            flexWrap="wrap"
            alignItems="center"
            justifyContent="flex-end"
            columnGap={isFull ? 2 : 1}
          >
            {autoCache}
            {autoCompact}
            {compact}
          </Box>
        </Box>
        {below}
      </Box>
    )
  })
}

