export type CacheView = {
  // When the main conversation last sent Claude a request, which is when its
  // cache was last read; 0 when not known yet.
  lastUsedAt: number
  ctxTokens: number
  // The conversation's size estimated after a compaction, until the next
  // reply reports the real one.
  ctxOverride: number | null
  now: number
}

// The two toggles, and what Auto cache's pings and Auto compact have done.
export type Warmth = {
  // Auto cache: ping the cache warm while the person is away.
  isOn: boolean
  // Auto compact: compact the conversation once it passes a size.
  isCompactOn: boolean
  // Pings since the conversation last sent a request of its own.
  pings: number
  isPinging: boolean
  // False until the conversation sends a request a ping can repeat: after a
  // compaction, after a ping found the cache already gone, or before anything
  // was sent in this session.
  isArmed: boolean
  // No ping before this time; set after a ping failed.
  retryAt: number
}

declare module 'claude-code' {
  interface PluginState {
    'cache-band': { view: CacheView | null; isCompacting: boolean; warmth: Warmth }
  }
}
